diff --git a/usbprotection.cpp b/usbprotection.cpp
new file mode 100644
index 00000000..d31976b0
--- /dev/null
+++ b/usbprotection.cpp
@@ -0,0 +1,207 @@
+/*
+SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+SPDX-License-Identifier: GPL-2.0-or-later
+*/
+#include "usbprotection.h"
+#include "kscreensaversettings.h"
+
+#include <KLocalizedString>
+#include <KNotification>
+
+#include <QDBusArgument>
+#include <QDBusConnection>
+#include <QDBusPendingCallWatcher>
+#include <QDBusPendingReply>
+#include <QRegularExpression>
+
+#include <kscreenlocker_logging.h>
+
+const static QString s_usbGuardService = QStringLiteral("org.usbguard1");
+const static QString s_usbGuardPath = QStringLiteral("/org/usbguard1");
+const static QString s_usbGuardInterface = QStringLiteral("org.usbguard1");
+const static QString s_usbGuardDevicesPath = QStringLiteral("/org/usbguard1/Devices");
+const static QString s_usbGuardDevicesInterface = QStringLiteral("org.usbguard.Devices1");
+const static QString s_insertedDevicePolicy = QStringLiteral("InsertedDevicePolicy");
+const static QString s_applyPolicy = QStringLiteral("apply-policy");
+const static QString s_block = QStringLiteral("block");
+
+// USBGuard's DevicePresenceChanged event and device policy target values
+constexpr uint s_eventInsert = 1;
+constexpr uint s_targetAllow = 0;
+constexpr uint s_targetBlock = 1;
+
+static QStringList interfacesOf(const QString &withInterface)
+{
+    QString interfaces = withInterface;
+    interfaces.remove(QLatin1Char('{')).remove(QLatin1Char('}'));
+    return interfaces.split(QLatin1Char(' '), Qt::SkipEmptyParts);
+}
+
+static bool isKeyboardInterface(const QString &interface)
+{
+    // HID boot keyboard, or HID keyboard without boot protocol
+    return interface == QLatin1String("03:01:01") || interface == QLatin1String("03:00:01");
+}
+
+static bool isOnlyKeyboard(const QStringList &interfaces)
+{
+    return std::ranges::any_of(interfaces, isKeyboardInterface) && std::ranges::all_of(interfaces, [](const QString &interface) {
+               return interface.startsWith(QLatin1String("03:"));
+           });
+}
+
+static QDBusMessage usbGuardCall(const QString &path, const QString &interface, const QString &method)
+{
+    return QDBusMessage::createMethodCall(s_usbGuardService, path, interface, method);
+}
+
+UsbProtection::UsbProtection(QObject *parent)
+    : QObject(parent)
+{
+}
+
+void UsbProtection::setLocked(bool locked)
+{
+    if (m_locked == locked) {
+        return;
+    }
+    m_locked = locked;
+    if (locked) {
+        if (KScreenSaverSettings::blockUsbDevicesWhileLocked()) {
+            startBlocking();
+        }
+    } else {
+        stopBlocking();
+    }
+}
+
+void UsbProtection::startBlocking()
+{
+    QDBusMessage message = usbGuardCall(s_usbGuardPath, s_usbGuardInterface, QStringLiteral("getParameter"));
+    message << s_insertedDevicePolicy;
+    auto watcher = new QDBusPendingCallWatcher(QDBusConnection::systemBus().asyncCall(message), this);
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this](QDBusPendingCallWatcher *self) {
+        self->deleteLater();
+        const QDBusPendingReply<QString> reply = *self;
+        // Don't touch the policy if USBGuard isn't running, or if it was set to something else on purpose
+        if (!m_locked || m_blocking || reply.isError() || reply.value() != s_applyPolicy) {
+            return;
+        }
+        m_blocking = true;
+        m_blockedDevices = 0;
+        QDBusConnection::systemBus().connect(s_usbGuardService,
+                                             s_usbGuardDevicesPath,
+                                             s_usbGuardDevicesInterface,
+                                             QStringLiteral("DevicePresenceChanged"),
+                                             this,
+                                             SLOT(devicePresenceChanged(QDBusMessage)));
+        QDBusMessage message = usbGuardCall(s_usbGuardPath, s_usbGuardInterface, QStringLiteral("setParameter"));
+        message << s_insertedDevicePolicy << s_block;
+        auto watcher = new QDBusPendingCallWatcher(QDBusConnection::systemBus().asyncCall(message), this);
+        connect(watcher, &QDBusPendingCallWatcher::finished, this, [](QDBusPendingCallWatcher *self) {
+            self->deleteLater();
+            if (self->isError()) {
+                qCWarning(KSCREENLOCKER) << "Could not block new USB devices:" << self->error().message();
+            }
+        });
+    });
+}
+
+void UsbProtection::stopBlocking()
+{
+    if (!m_blocking) {
+        return;
+    }
+    m_blocking = false;
+    QDBusConnection::systemBus().disconnect(s_usbGuardService,
+                                            s_usbGuardDevicesPath,
+                                            s_usbGuardDevicesInterface,
+                                            QStringLiteral("DevicePresenceChanged"),
+                                            this,
+                                            SLOT(devicePresenceChanged(QDBusMessage)));
+    QDBusMessage message = usbGuardCall(s_usbGuardPath, s_usbGuardInterface, QStringLiteral("setParameter"));
+    message << s_insertedDevicePolicy << s_applyPolicy;
+    QDBusConnection::systemBus().asyncCall(message);
+
+    if (m_blockedDevices > 0) {
+        KNotification::event(KNotification::Notification,
+                             i18np("USB device blocked", "USB devices blocked", m_blockedDevices),
+                             i18np("A USB device was connected while the screen was locked. Disconnect and reconnect it to use it.",
+                                   "%1 USB devices were connected while the screen was locked. Disconnect and reconnect them to use them.",
+                                   m_blockedDevices),
+                             QStringLiteral("drive-removable-media-usb"));
+    }
+    m_blockedDevices = 0;
+}
+
+void UsbProtection::devicePresenceChanged(const QDBusMessage &message)
+{
+    const QList<QVariant> arguments = message.arguments();
+    if (!m_blocking || arguments.size() < 5) {
+        return;
+    }
+    const uint id = arguments.at(0).toUInt();
+    const uint event = arguments.at(1).toUInt();
+    const uint target = arguments.at(2).toUInt();
+    if (event != s_eventInsert || target != s_targetBlock) {
+        return;
+    }
+    const auto attributes = qdbus_cast<QMap<QString, QString>>(arguments.at(4));
+
+    // Internal devices can show up again after resuming from sleep
+    const QString connectType = attributes.value(QStringLiteral("with-connect-type"));
+    if (connectType == QLatin1String("hardwired") || connectType == QLatin1String("not used")) {
+        allowDevice(id);
+        return;
+    }
+
+    if (!isOnlyKeyboard(interfacesOf(attributes.value(QStringLiteral("with-interface"))))) {
+        m_blockedDevices++;
+        return;
+    }
+
+    // Allow a keyboard only if there is no other one to unlock the session with
+    QDBusMessage listDevices = usbGuardCall(s_usbGuardDevicesPath, s_usbGuardDevicesInterface, QStringLiteral("listDevices"));
+    listDevices << QStringLiteral("allow");
+    auto watcher = new QDBusPendingCallWatcher(QDBusConnection::systemBus().asyncCall(listDevices), this);
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this, id](QDBusPendingCallWatcher *self) {
+        self->deleteLater();
+        if (!m_blocking) {
+            return;
+        }
+        const QDBusMessage reply = self->reply();
+        bool keyboardPresent = false;
+        if (reply.type() == QDBusMessage::ReplyMessage && !reply.arguments().isEmpty()) {
+            static const QRegularExpression withInterface(QStringLiteral("with-interface (\\{[^}]*\\}|\\S+)"));
+            const QDBusArgument devices = reply.arguments().constFirst().value<QDBusArgument>();
+            devices.beginArray();
+            while (!devices.atEnd()) {
+                uint deviceId;
+                QString rule;
+                devices.beginStructure();
+                devices >> deviceId >> rule;
+                devices.endStructure();
+                const QRegularExpressionMatch match = withInterface.match(rule);
+                if (deviceId != id && match.hasMatch() && std::ranges::any_of(interfacesOf(match.captured(1)), isKeyboardInterface)) {
+                    keyboardPresent = true;
+                }
+            }
+            devices.endArray();
+        }
+        if (keyboardPresent) {
+            m_blockedDevices++;
+        } else {
+            allowDevice(id);
+        }
+    });
+}
+
+void UsbProtection::allowDevice(uint id)
+{
+    QDBusMessage message = usbGuardCall(s_usbGuardDevicesPath, s_usbGuardDevicesInterface, QStringLiteral("applyDevicePolicy"));
+    message << id << s_targetAllow << false;
+    QDBusConnection::systemBus().asyncCall(message);
+}
+
+#include "moc_usbprotection.cpp"
diff --git a/usbprotection.h b/usbprotection.h
new file mode 100644
index 00000000..47e0342b
--- /dev/null
+++ b/usbprotection.h
@@ -0,0 +1,38 @@
+/*
+SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+SPDX-License-Identifier: GPL-2.0-or-later
+*/
+#pragma once
+
+#include <QDBusMessage>
+#include <QObject>
+
+/**
+ * Blocks USB devices plugged in while the screen is locked, through USBGuard.
+ *
+ * While locked, USBGuard's InsertedDevicePolicy is switched from apply-policy to block,
+ * and restored on unlock. A keyboard is still allowed if no other keyboard is connected,
+ * so that the session can always be unlocked. Devices blocked this way are reported
+ * in a notification after unlocking.
+ */
+class UsbProtection : public QObject
+{
+    Q_OBJECT
+public:
+    explicit UsbProtection(QObject *parent = nullptr);
+
+    void setLocked(bool locked);
+
+private Q_SLOTS:
+    void devicePresenceChanged(const QDBusMessage &message);
+
+private:
+    void startBlocking();
+    void stopBlocking();
+    void allowDevice(uint id);
+
+    bool m_locked = false;
+    bool m_blocking = false;
+    int m_blockedDevices = 0;
+};
